,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Ejecuta Reportes'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_clob 	CLOB;',
'BEGIN',
'    FOR W IN 1..APEX_APPLICATION.G_F01.COUNT LOOP',
'       IF APEX_APPLICATION.G_F01(W) = 1 THEN',
'           OC_REPORTES_APEX.GENERA_REPORTE_ADMINISTRATIVOS(1, 1, ''REPORTES'', ''ADMINISTRATIVOS'',',
'                                         ''MEDIOSCOB'', :P2_CodMoneda, :P2_IdTipoSeg, :P2_PlanCob,',
'                                         :P2_FecDesde, :P2_FecHasta, :P2_Formato, APEX_APPLICATION.G_F02(1));',
'        ELSIF APEX_APPLICATION.G_F01(W) = 2 THEN',
'            OC_REPORTES_APEX.GENERA_REPORTE_ADMINISTRATIVOS(1, 1, ''REPORTES'', ''ADMINISTRATIVOS'',',
'                                         ''FOLIOSFACT'', :P2_CodMoneda, :P2_IdTipoSeg, :P2_PlanCob,',
'                                         :P2_FecDesde, :P2_FecHasta, :P2_Formato, APEX_APPLICATION.G_F02(2));',
'',
'',
'           /*OC_REPORTES_APEX.GENERA_REPORTE_FOLIOS_FACT(1,1,',
'                                                       ''REPORTES'', --cModulo VARCHAR2, ',
'                                                       ''FOLIOSFACT'', --cCodReporte VARCHAR2, ',
'                                                       :P2_FecDesde, ',
'                                                       :P2_FecHasta, ',
'                                                       :P2_FORMATO, ',
'                                                       APEX_APPLICATION.G_F02(2)',
'                                                       );*/',
'           COMMIT;',
'        /*ELSIF APEX_APPLICATION.G_F01(W) = 3 THEN',
'           GT_REPORTES_COBRANZA.GENERAR_PAGADOS(nCodCia       => :G_NCODCIA, ',
'                                                cFormato      => :P100_FORMATO,',
'                                                cRutaArchivos => NULL,',
'                                                cNomArchivo   => APEX_APPLICATION.G_F02(3),',
'                                                cIdTipoSeg    => :P100_IDTIPOSEG, ',
'                                                cPlanCob      => :P100_PLANCOB, ',
'                                                cCodMoneda    => :P100_MONEDA, ',
'                                                cCodAgente    => :P100_CODAGENTE,',
'                                                dFecDesde     => :P100_FECHADESDE, ',
'                                                dFecHasta     => :P100_FECHAHASTA);',
'           COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 4 THEN',
'           GT_REPORTES_COBRANZA.GENERAR_ANULADOS(nCodCia       => :G_NCODCIA, ',
'                                                 cFormato      => :P100_FORMATO,',
'                                                 cRutaArchivos => NULL,',
'                                                 cNomArchivo   => APEX_APPLICATION.G_F02(4),',
'                                                 cIdTipoSeg    => :P100_IDTIPOSEG, ',
'                                                 cPlanCob      => :P100_PLANCOB, ',
'                                                 cCodMoneda    => :P100_MONEDA, ',
'                                                 cCodAgente    => :P100_CODAGENTE,',
'                                                 dFecDesde     => :P100_FECHADESDE, ',
'                                                 dFecHasta     => :P100_FECHAHASTA);',
'           COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 5 THEN',
'           GT_REPORTES_COBRANZA.GENERAR_DEUDOR(nCodCia       => :G_NCODCIA, ',
'                                               cFormato      => :P100_FORMATO,',
'                                               cRutaArchivos => NULL,',
'                                               cNomArchivo   => APEX_APPLICATION.G_F02(5),',
'                                               cIdTipoSeg    => :P100_IDTIPOSEG, ',
'                                               cPlanCob      => :P100_PLANCOB, ',
'                                               cCodMoneda    => :P100_MONEDA, ',
'                                               cCodAgente    => :P100_CODAGENTE,',
'                                               dFecDesde     => :P100_FECHADESDE, ',
'                                               dFecHasta     => :P100_FECHAHASTA);',
'           COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 6 THEN',
'           GT_REPORTES_COBRANZA.GENERAR_NCR(nCodCia       => :G_NCODCIA, ',
'                                            cFormato      => :P100_FORMATO,',
'                                            cRutaArchivos => NULL,',
'                                            cNomArchivo   => APEX_APPLICATION.G_F02(6),',
'                                            cIdTipoSeg    => :P100_IDTIPOSEG, ',
'                                            cPlanCob      => :P100_PLANCOB, ',
