'DECLARE',
'   l_clob 	CLOB;',
'BEGIN',
'    FOR W IN 1..APEX_APPLICATION.G_F01.COUNT LOOP',
'       IF APEX_APPLICATION.G_F01(W) = 1 THEN',
'            OC_REPORTES_APEX.GENERA_REPORTE_COMERCIAL(1, 1, ''REPORTES'', ''COMERCIAL'',',
'                                         ''POLXREN'', :P6_CodMoneda, :P6_IdTipoSeg, :P6_CodAgente,',
'                                         :P6_FecDesde, :P6_FecHasta, :P6_Formato, APEX_APPLICATION.G_F02(1));',
'        ELSIF APEX_APPLICATION.G_F01(W) = 2 THEN',
'            OC_REPORTES_APEX.GENERA_REPORTE_COMERCIAL(1, 1, ''REPORTES'', ''COMERCIAL'',',
'                                         ''CARTERA'', :P6_CodMoneda, :P6_IdTipoSeg, :P6_CodAgente,',
'                                         :P6_FecDesde, :P6_FecHasta, :P6_Formato, APEX_APPLICATION.G_F02(2));',
'           COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 3 THEN',
'            OC_REPORTES_APEX.GENERA_REPORTE_COMERCIAL(1, 1, ''REPORTES'', ''COMERCIAL'',',
'                                         ''RECIBOS360'', :P6_CodMoneda, :P6_IdTipoSeg, :P6_CodAgente,',
'                                         :P6_FecDesde, :P6_FecHasta, :P6_Formato, APEX_APPLICATION.G_F02(3));',
'           COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 4 THEN',
'            OC_REPORTES_APEX.GENERA_REPORTE_COMERCIAL(1, 1, ''REPORTES'', ''COMERCIAL'',',
'                                         ''FZAVENTAS'', :P6_CodMoneda, :P6_IdTipoSeg, :P6_CodAgente,',
'                                         :P6_FecDesde, :P6_FecHasta, :P6_Formato, APEX_APPLICATION.G_F02(4));',
'           COMMIT;',
'        /*ELSIF APEX_APPLICATION.G_F01(W) = 5 THEN',
'           COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 6 THEN',
'           COMMIT;*/',
'        END IF;',
'   END LOOP;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8482167257238910)
