 p_id=>wwv_flow_imp.id(8488499820316120)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Descarga Reportes Comercial'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_name varchar2(4000) := ''reportes_comercial.zip'';--||''.xls''; ',
'    l_mime_type varchar2(4000) :=  ''application/zip'';',
'    l_file_charset varchar2(100) := ''utf-8'';',
'    l_zip_file blob;',
'BEGIN',
'    FOR l_file IN (SELECT NombreArchivo,',
'                          Data',
'                     FROM TEMP_GEN_ARCHIVO',
'                    WHERE UPPER(CODUSER) = UPPER(:APP_USER))',
'    LOOP',
'        apex_zip.add_file (',
'            p_zipped_blob => l_zip_file,',
'            p_file_name   => l_file.NombreArchivo,',
'            p_content     => l_file.data );',
'    END LOOP;',
'',
'    apex_zip.finish (p_zipped_blob => l_zip_file );',
'',
'',
'  owa_util.mime_header(l_mime_type, false);',
'  sys.htp.p(''Content-length:''||dbms_lob.getlength(l_zip_file));',
'  sys.htp.p(''Content-Disposition: attachment; filename="''||l_file_name||''"; ''||''filename*=''||l_file_charset||''''''''''''||l_file_name);',
'  owa_util.http_header_close;',
'  wpg_docload.download_file(l_zip_file);',
'  OC_ARCHIVO.ELIMINAR_ARCHIVO(:APP_USER);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>8488499820316120
);
end;
