 p_id=>wwv_flow_imp.id(8788688388655105)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Ejecuta Reportes'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_clob 	CLOB;',
'BEGIN',
'    FOR W IN 1..APEX_APPLICATION.G_F01.COUNT LOOP',
'       IF APEX_APPLICATION.G_F01(W) = 1 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''PRODUCC'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(1));',
'                                         ',
'            COMMIT;                                         ',
'        ELSIF APEX_APPLICATION.G_F01(W) = 2 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''COMISIONES'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(2));',
'            COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 3 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''COBRANZA'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(3));',
'            COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 4 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''RENOVACION'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(4));',
'            COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 5 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''COMCOB'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(5));',
'            COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 6 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''CONTPOL'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(6));',
'            COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 7 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''EDOSCTA'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(7));',
'            COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 8 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''MORCOBRA'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(8));',
'            COMMIT;',
'        ELSIF APEX_APPLICATION.G_F01(W) = 9 THEN',
'            OC_REPORTES_APEX.GENERA_GENERALES(1, 1, ''REPORTES'', ''GENERALES'',',
'                                         ''CLIENTES'', :P11_CodMoneda, :P11_IdTipoSeg, :P11_FecDesde, ',
'                                         :P11_FecHasta, :P11_CodCliente, :P11_FecMorosidad, ',
'                                         :P11_Formato, APEX_APPLICATION.G_F02(9));',
'            COMMIT;',
'        END IF;',
'   END LOOP;',
'END;',
''))
